function getListingMarketingDraftStorageKey(listingId) {
  const normalizedId = String(listingId || '').trim()
  return normalizedId ? `${LISTING_MARKETING_DRAFT_STORAGE_KEY}:${normalizedId}` : ''
}

function buildLightweightMarketingDraft(draft = {}) {
  const safeDraft = draft && typeof draft === 'object' ? draft : {}
  return {
    headline: String(safeDraft.headline || '').trim(),
    description: String(safeDraft.description || '').trim(),
    listingPreviewDescription: String(safeDraft.listingPreviewDescription || '').trim(),
    propertySubtype: String(safeDraft.propertySubtype || '').trim(),
    propertyCategory: String(safeDraft.propertyCategory || 'residential').trim(),
    exactAddressVisibility: String(safeDraft.exactAddressVisibility || 'hide_street_address').trim(),
    pricePresentation: String(safeDraft.pricePresentation || 'Standard').trim(),
    offersFrom: String(safeDraft.offersFrom || '').trim(),
    rentalPricePeriod: String(safeDraft.rentalPricePeriod || 'PerMonth').trim(),
    availableFrom: formatDateInputValue(safeDraft.availableFrom),
    furnished: Boolean(safeDraft.furnished),
    selectedFeatures: Array.isArray(safeDraft.selectedFeatures) ? safeDraft.selectedFeatures.map(String).filter(Boolean) : [],
    featureFacts: normalizeListingFeatureFacts(safeDraft.featureFacts, safeDraft.selectedFeatures),
    showReducedBanner: Boolean(safeDraft.showReducedBanner),
    amenities: Array.isArray(safeDraft.amenities) ? safeDraft.amenities.map(String).filter(Boolean) : [],
    videoLink: String(safeDraft.videoLink || '').trim(),
    virtualTourLink: String(safeDraft.virtualTourLink || '').trim(),
    property24ListingUrl: String(safeDraft.property24ListingUrl || '').trim(),
    property24Reference: String(safeDraft.property24Reference || '').trim(),
    property24Status: String(safeDraft.property24Status || '').trim(),
    property24ExpiryDate: formatDateInputValue(safeDraft.property24ExpiryDate),
    property24SuburbId: String(safeDraft.property24SuburbId || '').trim(),
    privatePropertySuburbId: String(safeDraft.privatePropertySuburbId || '').trim(),
    privatePropertyListingUrl: String(safeDraft.privatePropertyListingUrl || '').trim(),
    privatePropertyReference: String(safeDraft.privatePropertyReference || '').trim(),
    privatePropertyStatus: String(safeDraft.privatePropertyStatus || '').trim(),
    bridgeListingStatus: String(safeDraft.bridgeListingStatus || '').trim(),
    bridgeListingPublicUrl: String(safeDraft.bridgeListingPublicUrl || '').trim(),
    externalLinks: normalizeExternalListingLinks(safeDraft.externalLinks),
    savedAt: new Date().toISOString(),
  }
}

function hasMeaningfulMarketingDraft(draft = {}) {
  if (!draft || typeof draft !== 'object') return false
  return Boolean(
    String(draft.description || '').trim() ||
      String(draft.listingPreviewDescription || '').trim() ||
      (Array.isArray(draft.selectedFeatures) && draft.selectedFeatures.length) ||
      (Array.isArray(draft.amenities) && draft.amenities.length) ||
      (draft.featureFacts && Object.keys(draft.featureFacts).length > 0),
  )
}

function isStoredMarketingDraftNewerThanListing(draft = {}, listing = {}) {
  const savedAt = Date.parse(String(draft?.savedAt || ''))
  const updatedAt = Date.parse(String(listing?.updatedAt || listing?.updated_at || ''))
  return Number.isFinite(savedAt) && (!Number.isFinite(updatedAt) || savedAt > updatedAt)
}

function readStoredMarketingDraft(listingId) {
  const storageKey = getListingMarketingDraftStorageKey(listingId)
  if (!storageKey || typeof window === 'undefined') return null
  try {
    const stored = window.localStorage.getItem(storageKey)
    if (!stored) return null
    const parsed = JSON.parse(stored)
    return parsed && typeof parsed === 'object' ? parsed : null
  } catch {
    window.localStorage.removeItem(storageKey)
    return null
  }
}

function writeStoredMarketingDraft(listingId, draft) {
  const storageKey = getListingMarketingDraftStorageKey(listingId)
  if (!storageKey || typeof window === 'undefined') return
  try {
    window.localStorage.setItem(storageKey, JSON.stringify(buildLightweightMarketingDraft(draft)))
  } catch (storageError) {
    console.warn('[AgentListingDetail] marketing draft cache write skipped', storageError)
  }
}

function clearStoredMarketingDraft(listingId) {
  const storageKey = getListingMarketingDraftStorageKey(listingId)
  if (!storageKey || typeof window === 'undefined') return
  window.localStorage.removeItem(storageKey)
}

function buildAddressAutocompleteValueFromDraft(draft = {}) {
  const formattedAddress = String(
    draft.formattedAddress ||
      [draft.addressLine1 || draft.streetAddress, draft.suburb, draft.city, draft.province].filter(Boolean).join(', '),
  ).trim()

  if (!formattedAddress) return null

  return {
    formattedAddress,
    streetAddress: String(draft.streetAddress || draft.addressLine1 || '').trim(),
    suburb: String(draft.suburb || '').trim(),
    city: String(draft.city || '').trim(),
    province: String(draft.province || '').trim(),
    country: String(draft.country || 'South Africa').trim(),
    postalCode: String(draft.postalCode || '').trim(),
    latitude: typeof draft.latitude === 'number' ? draft.latitude : Number(draft.latitude) || undefined,
    longitude: typeof draft.longitude === 'number' ? draft.longitude : Number(draft.longitude) || undefined,
    placeId: String(draft.googlePlaceId || '').trim(),
  }
}

function mergeAddressIntoMarketingDraft(previous, value) {
  if (!value) {
    return {
      ...previous,
      formattedAddress: '',
      streetAddress: '',
      addressLine1: '',
      suburb: '',
      city: '',
      province: '',
      country: 'South Africa',
      postalCode: '',
      latitude: null,
      longitude: null,
      googlePlaceId: '',
    }
  }

  return {
    ...previous,
    formattedAddress: value.formattedAddress || '',
    streetAddress: value.streetAddress || value.formattedAddress || '',
    addressLine1: value.streetAddress || value.formattedAddress || '',
    suburb: value.suburb || '',
    city: value.city || '',
    province: value.province || '',
    country: value.country || 'South Africa',
    postalCode: value.postalCode || '',
    latitude: value.latitude ?? null,
    longitude: value.longitude ?? null,
    googlePlaceId: value.placeId || '',
  }
}

function ListingPostCreateProgressCard({ progress = null, onRetrySellerPortal = null, retryingSellerPortal = false } = {}) {
  if (!progress?.tasks) return null
  const tasks = Object.entries(progress.tasks)
  const complete = Boolean(progress.completedAt)
  const Icon = ({ status }) => {
    if (status === 'complete' || status === 'skipped') return <CheckCircle2 size={16} className="text-[#1f7d44]" />
    if (status === 'attention') return <CircleAlert size={16} className="text-[#b7791f]" />
    if (status === 'in_progress') return <Loader2 size={16} className="animate-spin text-[#1f4f78]" />
    return <Circle size={16} className="text-[#8ca0b5]" />
  }

  return (
    <section aria-live="polite" className="overflow-hidden rounded-[18px] border border-[#cfe0ef] bg-[#f7fbff] shadow-[0_10px_24px_rgba(15,23,42,0.045)]">
      <div className="flex items-start gap-3 border-b border-[#dce8f3] px-4 py-3">
        {complete ? <CheckCircle2 size={18} className="mt-0.5 text-[#1f7d44]" /> : <Loader2 size={18} className="mt-0.5 animate-spin text-[#1f4f78]" />}
        <div>
          <p className="text-sm font-semibold text-[#18324b]">{complete ? 'Listing setup complete' : 'Finishing listing setup'}</p>
          <p className="mt-0.5 text-sm text-[#607387]">{complete ? 'Your listing is ready to continue working on.' : 'You can continue working while these steps finish.'}</p>
        </div>
      </div>
      <div className="grid gap-2 p-4 sm:grid-cols-2">
        {tasks.map(([key, task]) => (
          <div key={key} className="flex items-center gap-2 rounded-[10px] bg-white px-3 py-2 text-sm font-medium text-[#35546c]">
            <Icon status={task?.status} />
            <span>{task?.label || key}</span>
            {key === 'sellerPortal' && task?.status === 'attention' && onRetrySellerPortal ? (
              <button
                type="button"
                onClick={onRetrySellerPortal}
                disabled={retryingSellerPortal}
                className="ml-auto rounded-[7px] border border-[#d8a75e] px-2 py-1 text-xs font-semibold text-[#8a5814] disabled:opacity-60"
              >
                {retryingSellerPortal ? 'Queueing…' : 'Retry'}
              </button>
            ) : null}
          </div>
        ))}
      </div>
    </section>
  )
}

