  async function publishProperty24Listing() {
    if (!ensureMarketingMediaReady(marketingDraft, 'publishing to Property24')) return null
    const expiryError = getProperty24ExpiryDateError(marketingDraft.property24ExpiryDate)
    if (expiryError) {
      setDetailMessage('')
      setDetailError(expiryError)
      return null
    }
    setProperty24Action('publish')
    setDetailError('')
    setDetailMessage('Publishing to Property24...')
    let publicationTracked = false
    try {
      const saveResult = await saveMarketingDraft(marketingDraft, {
        successMessage: '',
      })
      if (saveResult?.ok === false) throw saveResult.error || new Error('Save the listing before publishing to Property24.')
      await recordListingPublicationStage('Property24', 'submitted', marketingDraft, {
        action: property24Reference ? 'update' : 'publish',
        reference: property24Reference,
      })
      publicationTracked = true
      const payload = await callProperty24ListingAction('publish', getProperty24ActionContext(), { fallbackMessage: 'Property24 publish failed.' })
      setProperty24Preview(payload)
      const listingNumber = getProperty24ListingNumberFromResponse(payload)
      const confirmedStatus = payload?.report?.databaseWrite?.property24Status || 'draft'
      const nextDraft = {
        ...marketingDraft,
        property24Reference: listingNumber || marketingDraft.property24Reference,
        property24Status: confirmedStatus,
        property24ListingUrl: payload?.report?.databaseWrite?.property24ListingUrl || marketingDraft.property24ListingUrl,
      }
      setMarketingDraft(nextDraft)
      const statusSave = await saveMarketingDraft(nextDraft, { successMessage: '' })
      if (statusSave?.ok === false) {
        throw statusSave.error || new Error('Property24 accepted the listing, but Arch9 could not save its publication status. Please retry from this listing.')
      }
      await recordListingPublicationStage('Property24', 'accepted', nextDraft, {
        action: property24Reference ? 'update' : 'publish',
        reference: listingNumber || property24Reference,
        publicUrl: nextDraft.property24ListingUrl,
      })
      await loadListingData()
      openSellerWorkspaceSection('marketing')
      setDetailError('')
      setDetailMessage(confirmedStatus === 'published'
        ? `Property24 confirms this listing is live${listingNumber ? ` (number ${listingNumber})` : ''}.`
        : `Submitted to Property24${listingNumber ? ` (number ${listingNumber})` : ''}. Refresh status to confirm when it is live.`)
      return payload
    } catch (error) {
      if (publicationTracked) {
        await recordListingPublicationStage('Property24', 'failed', marketingDraft, {
          action: property24Reference ? 'update' : 'publish',
          reference: property24Reference,
          error: error?.message || 'Property24 publication failed.',
        }).catch(() => null)
        await loadListingData({ showLoading: false })
      }
      setDetailMessage('')
      setDetailError(error?.message || 'Property24 publish failed.')
      return null
    } finally {
      setProperty24Action('')
    }
  }

  async function callPrivatePropertyListingAction(action, body = {}, options = {}) {
    if (!listingRecord?.id) throw new Error('Open a saved listing before using Private Property.')
    if (!isSupabaseConfigured || !supabase) throw new Error('Sign in before using Private Property publishing.')
    const sessionResult = await supabase.auth.getSession()
    const accessToken = sessionResult.data?.session?.access_token
    if (!accessToken) throw new Error('Sign in again before using Private Property publishing.')
    const method = String(options.method || 'POST').toUpperCase()
    const queryParams = options.query instanceof URLSearchParams
      ? new URLSearchParams(options.query)
      : new URLSearchParams()
    queryParams.set('environment', 'production')
    const query = `?${queryParams.toString()}`
    const requestOptions = {
      method,
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    }
    if (method !== 'GET') {
      requestOptions.headers['Content-Type'] = 'application/json'
      requestOptions.body = JSON.stringify({
        environment: 'production',
        photosChanged: true,
        ...body,
      })
    }
    const response = await fetch(`${PRIVATE_PROPERTY_LISTING_API_BASE_PATH}/${encodeURIComponent(listingRecord.id)}/${action}${query}`, requestOptions)
    const payload = await response.json().catch(() => ({}))
    if (!response.ok) {
      throw new Error(getPrivatePropertyApiMessage(payload, options.fallbackMessage || 'Private Property request failed.'))
    }
    return payload
  }

  async function openSyndicationReview({ requiredForChannel = '', showModal = true } = {}) {
    setSyndicationReviewOpen(showModal)
    setSyndicationReviewLoading(true)
    setDetailError('')
    try {
      const saveResult = await saveMarketingDraft(marketingDraft, { successMessage: '' })
      if (saveResult?.ok === false) throw saveResult.error || new Error('Save the listing before reviewing channel settings.')
      const payload = await callPrivatePropertyListingAction('syndication-review', {}, { method: 'GET', fallbackMessage: 'Channel review could not be loaded.' })
      const review = payload?.review || null
      setSyndicationReview(review)
      if (requiredForChannel) setSyndicationReviewAcknowledgements((previous) => ({ ...previous, [requiredForChannel]: false }))
      return review
    } catch (error) {
      setDetailError(error?.message || 'Channel review could not be loaded.')
      return null
    } finally {
      setSyndicationReviewLoading(false)
    }
  }

  async function requireSyndicationReviewBeforePublish(channel) {
    const currentReview = syndicationReview
    const acknowledged = Boolean(syndicationReviewAcknowledgements[channel])
    if (!shouldRequireSyndicationReview({
      review: currentReview,
      channel,
      acknowledged,
      draftDirty: marketingDraftDirtyRef.current,
    })) {
      if (currentReview) return true
      const review = await openSyndicationReview({ requiredForChannel: channel, showModal: false })
      const reviewRequired = shouldRequireSyndicationReview({
        review,
        channel,
        acknowledged: false,
        draftDirty: marketingDraftDirtyRef.current,
      })
      if (reviewRequired) setSyndicationReviewOpen(true)
      return !reviewRequired
    }
    await openSyndicationReview({ requiredForChannel: channel })
    return false
  }

  function continueSyndicationReview(channel, action) {
    if (canAcknowledgeSyndicationChannel(syndicationReview, channel)) {
      setSyndicationReviewAcknowledgements((previous) => ({ ...previous, [channel]: true }))
    }
    setSyndicationReviewOpen(false)
    void action()
  }

