        notes: previous.notes,
        mode: previous.mode,
        sellerName: previous.sellerName,
        sellerEmail: previous.sellerEmail,
        sellerPhone: previous.sellerPhone,
        bookingConfirmedWithAll: previous.bookingConfirmedWithAll,
